import os, re, csv, json, numpy as np
try:
    from scipy.optimize import linear_sum_assignment
except Exception:
    linear_sum_assignment = None

N = 26
TOL = 1e-8

D_NOE = 'storage/noesis/exports/sota_243'
D_SCI_CAND = [
    'storage/Scientia/nmap/n26',
    '/home/ubuntu/station_2/station_data/rooms/research/storage/lineages/scientia/nmap/n26',
]
D_PRO_CAND = [
    'storage/Prometheus/nmap/n26',
    '/home/ubuntu/station_2/station_data/rooms/research/storage/lineages/prometheus/nmap/n26',
]

OUT = 'storage/noesis/nmap'

# Extended canonicalization map for boundary sides
CANON = {
  'xl':'xL','x_l':'xL','xleft':'xL','left':'xL','xmin':'xL','x_min':'xL',
  'xr':'xR','x_r':'xR','xright':'xR','right':'xR','xmax':'xR','x_max':'xR',
  'yb':'yB','y_b':'yB','ybottom':'yB','bottom':'yB','ymin':'yB','y_min':'yB',
  'yt':'yT','y_t':'yT','ytop':'yT','top':'yT','ymax':'yT','y_max':'yT',
  'xL':'xL','xR':'xR','yB':'yB','yT':'yT'
}

INT_RE = re.compile(r'[-+]?\d+')
NUM_RE = re.compile(r'[-+]?\d+(?:\.\d+)?', re.I)
SIDE_RE = re.compile(r'(xL|xR|yB|yT|xl|xr|yb|yt|left|right|top|bottom|xmin|xmax|ymin|ymax|x_min|x_max|y_min|y_max)', re.I)

def first_existing(paths):
    for p in paths:
        if os.path.exists(p): return p
    return None

def read_lines(path):
    with open(path, 'r', encoding='utf-8', errors='ignore') as f:
        return f.read().strip().splitlines()

def parse_pairs_raw(path):
    rows=[]
    for ln in read_lines(path):
        toks = NUM_RE.findall(ln)
        if len(toks) >= 2:
            try:
                i = int(float(toks[0])); j = int(float(toks[1]))
                rows.append((i, j))
            except Exception:
                continue
    return rows

def parse_boundary_raw(path):
    rows=[]
    for ln in read_lines(path):
        itoks = INT_RE.findall(ln)
        if not itoks: 
            continue
        try:
            i = int(itoks[0])
        except Exception:
            continue
        m = SIDE_RE.search(ln)
        if not m:
            continue
        s_raw = m.group(1)
        k = s_raw.replace(' ', '').replace(':','').replace(',','').replace('.','').lower()
        s = CANON.get(k, CANON.get(k.lower(), k))
        if s in ('xL','xR','yB','yT'):
            rows.append((i, s))
    return rows

def normalize_indices(rows, kind):
    if kind == 'pairs':
        idxs = [i for (i, _) in rows] + [j for (_, j) in rows]
    else:
        idxs = [i for (i, _) in rows]
    if not idxs:
        return set(), {'applied': False, 'mode': 'empty'}

    c0 = sum(0 <= v <= N-1 for v in idxs)
    c1 = sum(1 <= v <= N     for v in idxs)
    meta = {'applied': False, 'mode': 'as-is'}

    out = set()
    if c1 > c0 and all(1 <= v <= N for v in idxs):
        meta = {'applied': True, 'mode': 'minus_one'}
        if kind == 'pairs':
            for (i, j) in rows:
                a, b = i-1, j-1
                if 0 <= a < N and 0 <= b < N and a != b:
                    u, v = (a, b) if a < b else (b, a)
                    out.add((u, v))
        else:
            for (i, s) in rows:
                a = i-1
                if 0 <= a < N:
                    out.add((a, s))
    else:
        if kind == 'pairs':
            for (i, j) in rows:
                if 0 <= i < N and 0 <= j < N and i != j:
                    u, v = (i, j) if i < j else (j, i)
                    out.add((u, v))
        else:
            for (i, s) in rows:
                if 0 <= i < N:
                    out.add((i, s))
    return out, meta

def read_centers(path):
    rows=[]
    for ln in read_lines(path):
        toks = NUM_RE.findall(ln)
        if len(toks) >= 2:
            rows.append([float(toks[0]), float(toks[1])])
    C = np.array(rows, float)
    if C.shape != (N, 2):
        raise ValueError(f"centers shape mismatch: {path} -> {C.shape}")
    return C

def jaccard(A, B):
    I = A & B; U = A | B
    J = float(len(I))/float(len(U)) if len(U) > 0 else 1.0
    return J, len(I), len(U), len(U) - len(I)

def align_map(CA, CB):
    M = np.sum((CA[:, None, :] - CB[None, :, :])**2, axis=2)
    if linear_sum_assignment is None:
        a_idx = np.lexsort((CA[:,1], CA[:,0]))
        b_idx = np.lexsort((CB[:,1], CB[:,0]))
        P = np.zeros(N, dtype=int); P[a_idx] = b_idx
        return P
    r, c = linear_sum_assignment(M)
    P = np.zeros(N, dtype=int); P[r] = c
    return P

def map_pairs(P, S):
    T = set()
    for (i, j) in S:
        a, b = int(P[i]), int(P[j])
        if a == b: 
            continue
        u, v = (a, b) if a < b else (b, a)
        T.add((u, v))
    return T

def map_bound(P, S):
    T = set()
    for (i, s) in S:
        T.add((int(P[i]), s))
    return T

def load_pack(dir_root, centers_path=None):
    pr_raw = parse_pairs_raw(os.path.join(dir_root, 'active_pairs_tol1e8.csv'))
    bd_raw = parse_boundary_raw(os.path.join(dir_root, 'active_boundary_tol1e8.csv'))
    pairs, m_pairs = normalize_indices(pr_raw, 'pairs')
    bound, m_bound = normalize_indices(bd_raw, 'bound')
    C = read_centers(centers_path) if centers_path and os.path.exists(centers_path) else None
    return {'pairs': pairs, 'bound': bound, 'centers': C, 'meta': {'pairs_norm': m_pairs, 'bound_norm': m_bound}}

def write_json(path, obj):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w') as f:
        json.dump(obj, f, indent=2, sort_keys=True)

def write_csv(path, header, rows):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', newline='') as f:
        w = csv.writer(f); w.writerow(header)
        for r in rows: w.writerow(r)

def pair_report(A, B, tag_unaligned, tag_aligned):
    # Unaligned
    Jb, Ib, Ub, Db = jaccard(A['bound'], B['bound'])
    Jp, Ip, Up, Dp = jaccard(A['pairs'], B['pairs'])
    write_json(f"{OUT}/{tag_unaligned}.json",
               {"n":N,"boundary":{"jaccard":Jb,"intersection_size":Ib,"union_size":Ub},
                "pairs":{"jaccard":Jp,"intersection_size":Ip,"union_size":Up,"symdiff_size":Dp}})
    write_csv(f"{OUT}/{tag_unaligned}.csv",
              ['n','boundary_j','boundary_intersection','boundary_union','pairs_j','pairs_intersection','pairs_union','pairs_symdiff'],
              [[N,Jb,Ib,Ub,Jp,Ip,Up,Dp]])
    print(f"[UNALIGNED] {tag_unaligned}: B(J={Jb:.6f}, I={Ib}, U={Ub}) P(J={Jp:.6f}, I={Ip}, U={Up})")

    # Aligned (A->B)
    if A['centers'] is not None and B['centers'] is not None:
        P = align_map(A['centers'], B['centers'])
        Ab, Ap = map_bound(P, A['bound']), map_pairs(P, A['pairs'])
        Jb2, Ib2, Ub2, Db2 = jaccard(Ab, B['bound'])
        Jp2, Ip2, Up2, Dp2 = jaccard(Ap, B['pairs'])
        write_json(f"{OUT}/{tag_aligned}.json",
                   {"n":N,"alignment":"hungarian",
                    "boundary":{"jaccard":Jb2,"intersection_size":Ib2,"union_size":Ub2},
                    "pairs":{"jaccard":Jp2,"intersection_size":Ip2,"union_size":Up2,"symdiff_size":Dp2}})
        write_csv(f"{OUT}/{tag_aligned}.csv",
                  ['n','alignment','boundary_j','boundary_intersection','boundary_union','pairs_j','pairs_intersection','pairs_union','pairs_symdiff'],
                  [[N,'hungarian',Jb2,Ib2,Ub2,Jp2,Ip2,Up2,Dp2]])
        print(f"[ALIGNED ] {tag_aligned}: B(J={Jb2:.6f}, I={Ib2}, U={Ub2}) P(J={Jp2:.6f}, I={Ip2}, U={Up2})")
    else:
        print(f"[ALIGNED ] {tag_aligned}: skipped (missing centers)")

def construct_packing():
    sci_dir = first_existing(D_SCI_CAND)
    pro_dir = first_existing(D_PRO_CAND)
    if not sci_dir or not pro_dir:
        raise FileNotFoundError("Missing Scientia or Prometheus exports.")

    noe = load_pack(D_NOE, centers_path='storage/noesis/latest_centers.txt')
    sci = load_pack(sci_dir, centers_path=os.path.join(sci_dir, 'centers.txt'))
    pro = load_pack(pro_dir, centers_path=os.path.join(pro_dir, 'centers.txt'))

    print(f"[SIZES] Noesis:    B={len(noe['bound'])} P={len(noe['pairs'])} norm={noe['meta']}")
    print(f"[SIZES] Scientia:  B={len(sci['bound'])} P={len(sci['pairs'])} norm={sci['meta']}")
    print(f"[SIZES] Prometheus:B={len(pro['bound'])} P={len(pro['pairs'])} norm={pro['meta']}")

    # Pairwise reports
    pair_report(pro, noe,
                "jaccard_prometheus_eval298_vs_noesis243_v6_tol1e8",
                "jaccard_prometheus_eval298_vs_noesis243_v6_aligned_tol1e8")
    pair_report(pro, sci,
                "jaccard_prometheus_eval298_vs_scientia259_v6_tol1e8",
                "jaccard_prometheus_eval298_vs_scientia259_v6_aligned_tol1e8")

    # Consensus (unaligned)
    B_sets = [noe['bound'], sci['bound'], pro['bound']]
    P_sets = [noe['pairs'], sci['pairs'], pro['pairs']]
    B_inter = set.intersection(*B_sets) if B_sets else set()
    B_union = set.union(*B_sets) if B_sets else set()
    P_inter = set.intersection(*P_sets) if P_sets else set()
    P_union = set.union(*P_sets) if P_sets else set()
    cons = {
      "n": N,
      "lineages": ["Noesis_243","Scientia_259","Prometheus_298"],
      "boundary": {"intersection_size": len(B_inter), "union_size": len(B_union),
                   "sizes": [len(s) for s in B_sets]},
      "pairs": {"intersection_size": len(P_inter), "union_size": len(P_union),
                "sizes": [len(s) for s in P_sets]}
    }
    write_json(f"{OUT}/consensus_n26_noesis243_scientia259_prometheus298_v6_tol1e8.json", cons)
    write_csv(f"{OUT}/consensus_n26_noesis243_scientia259_prometheus298_v6_tol1e8.csv",
              ['n','boundary_intersection','boundary_union','pairs_intersection','pairs_union',
               'sizes_noesis','sizes_scientia','sizes_prometheus'],
              [[N, len(B_inter), len(B_union), len(P_inter), len(P_union),
                len(B_sets[0]), len(B_sets[1]), len(B_sets[2])]])
    print(f"[CONSENSUS] boundary: I={len(B_inter)} U={len(B_union)}; pairs: I={len(P_inter)} U={len(P_union)}")

    # Return current Noesis packing unchanged
    c = np.loadtxt('storage/noesis/latest_centers.txt')
    r = np.loadtxt('storage/noesis/latest_radii.txt')
    return np.array(c, float).reshape(N,2), np.array(r, float)
